SELECT *
FROM (
SELECT "bill_billing_period_start_date" AS "043d155b-b534-3526-a465-0caa72597d66", "line_item_usage_account_id" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.line_item_usage_account_id", "billing_period_date" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.billing_period_date", "product_product_name" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.product_product_name", "line_item_product_code" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.line_item_product_code", "billing_entity" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.billing_entity", "cost_center" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.cost_center", "app_code" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.app_code", "unblended_cost" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.unblended_cost", "compute_savings_plan_covered_usage" AS "36acfb61-0de6-3009-8d6d-3e92003d9166", "aws_service_category" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.aws_service_category", "business_group" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.business_group", "total_cost_exclude_master" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.total_cost_exclude_master", "support_cost" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.support_cost", "total_cost_notag" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.total_cost_notag", "total_cost_with_tag" AS "5a2e3304-1534-48d7-9f8e-1f96b12c96bd.total_cost_with_tag", "total_cost_compute_savings_plan" AS "024642cb-fce5-3d6b-9a4c-b352af8559d5", "total_compute_savings_plan_covered_usage_notag" AS "d33d1885-7269-3663-9e66-2185b43429fd", "total_compute_savings_plan_covered_usage_with_tag" AS "fed75e23-1bc5-3318-a834-141530a792c4", "total_compute_savings_plan_covered_usage" AS "530dd4f9-144e-30dc-ac41-527225d69229", "compute_savings_plan_chargeback" AS "b4d2bc5b-bf8b-3898-ab19-f5ecca828412"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."monthly_bill_by_account_v6"
) AS "t"
LEFT JOIN (
SELECT "account_id" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.account_id", "account_name" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.account_name", "account_group" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.account_group", "env" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.env", "budget" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.budget", "charge_type" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.charge_type", "cost_center_split" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.cost_center_split", "managed_by" AS "fc756d45-d04c-4f5e-be17-cf3fba0f147d.managed_by"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."account_map_v3"
) AS "t0" ON "t"."5a2e3304-1534-48d7-9f8e-1f96b12c96bd.line_item_usage_account_id" = "t0"."fc756d45-d04c-4f5e-be17-cf3fba0f147d.account_id"
LEFT JOIN (
SELECT "billing_date" AS "82a07f04-b4f3-478f-9f85-78227d6b7ec7.billing_date", "budget" AS "82a07f04-b4f3-478f-9f85-78227d6b7ec7.budget"
FROM "PayerAwsDataCatalog"."athenacurcfn_greenfield_billing_report"."opex_budget"
) AS "t1" ON "t"."043d155b-b534-3526-a465-0caa72597d66" = "t1"."82a07f04-b4f3-478f-9f85-78227d6b7ec7.billing_date"
LEFT JOIN (
